css:
/* 30mm x 20mm barcode label.
   Frappe reads the PDF page size off the .print-format rule; @page keeps the
   browser's own print dialog on the same size. page-width/page-height without a
   page-size is deliberate - a page-size here reaches wkhtmltopdf as an unknown
   paper name and aborts the PDF. */
@page {
	size: 30mm 20mm;
	margin: 0;
}

.print-format {
	page-width: 30mm;
	page-height: 20mm;
	margin-top: 0mm;
	margin-bottom: 0mm;
	margin-left: 0mm;
	margin-right: 0mm;
	width: 100% !important;
	max-width: none !important;
	min-height: 0 !important;
	padding: 0 !important;
	border-radius: 0 !important;
	font-family: Arial, Helvetica, sans-serif;
	color: #000;
}

body,
.print-format-gutter {
	margin: 0 !important;
	padding: 0 !important;
	background: #fff;
}

/* wm- prefix on purpose: frappe's print bundle ships bootstrap's .label badge
   (display: inline, white-space: nowrap), which silently wrecks the layout. */
.wm-label {
	box-sizing: border-box;
	width: 100%;
	padding: 4% 4% 2%;
	text-align: center;
}

/* height comes from padding-bottom, which resolves against the label's width -
   the one length wkhtmltopdf maps to the paper reliably. background-size then
   stretches the barcode to it, so every code length gets the same bar height. */
.wm-barcode {
	width: 100%;
	height: 0;
	padding-bottom: 38%;
	background-position: center;
	background-repeat: no-repeat;
	background-size: 100% 100%;
}

.wm-code {
	font-size: 6pt;
	line-height: 1.2;
	letter-spacing: 0.2pt;
}

.wm-name {
	max-height: 2.4em;
	overflow: hidden;
	font-size: 6pt;
	line-height: 1.2;
}

html:
{%- set row = doc.barcodes[0] if doc.barcodes else None -%}
{%- set image = get_barcode_image(row.barcode, row.barcode_type) if row else "" -%}
<div class="wm-label">
	{%- if image %}
	<div class="wm-barcode" style="background-image: url('{{ image }}')"></div>
	<div class="wm-code">{{ row.barcode }}</div>
	{%- else %}
	<div class="wm-code">{{ _("No barcode") }}</div>
	{%- endif %}
	<div class="wm-name">{{ doc.item_name or doc.item_code }}</div>
</div>
